style.css:
@-moz-document domain("userstyles.org") {
:root {
    --neon-cyan: #72e7ff;
    --neon-purple: #b99cff;
    --neon-blue: #8ab4ff;

    --bg-main: #080c12;
    --bg-secondary: #0d131c;
    --bg-card: rgba(18, 27, 38, 0.82);

    --text-main: #dce7f2;
    --text-bright: #eef8ff;
    --text-secondary: #91a2b5;
    --text-muted: #66788b;

    --border: rgba(114, 231, 255, 0.14);
}


/* ========================================================
   PAGE
   ======================================================== */

html {
    background:
        radial-gradient(
            circle at 10% 10%,
            rgba(114, 231, 255, 0.08),
            transparent 30%
        ),
        radial-gradient(
            circle at 90% 15%,
            rgba(185, 156, 255, 0.08),
            transparent 32%
        ),
        radial-gradient(
            circle at 50% 100%,
            rgba(80, 120, 255, 0.06),
            transparent 38%
        ),
        var(--bg-main) !important;

    color-scheme: dark !important;
}


body {
    background:
        radial-gradient(
            circle at 15% 20%,
            rgba(114, 231, 255, 0.025),
            transparent 28%
        ),
        radial-gradient(
            circle at 85% 75%,
            rgba(185, 156, 255, 0.025),
            transparent 30%
        ),
        var(--bg-main) !important;

    color:
        var(--text-main) !important;
}


/* ========================================================
   TEXT
   ======================================================== */

body,
p,
li,
span,
label,
td,
th {
    color:
        var(--text-main) !important;
}


h1,
h2,
h3,
h4,
h5,
h6 {
    color:
        var(--text-bright) !important;

    text-shadow:
        0 0 10px rgba(114, 231, 255, 0.14);
}


/* ========================================================
   LINKS
   ======================================================== */

a {
    color:
        var(--neon-cyan) !important;

    transition:
        color 0.2s ease,
        text-shadow 0.2s ease;
}


a:hover {
    color:
        #c6f8ff !important;

    text-shadow:
        0 0 9px rgba(114, 231, 255, 0.45);
}


/* ========================================================
   HEADER / NAVIGATION
   ======================================================== */

header,
nav {
    background:
        rgba(9, 15, 22, 0.82) !important;

    border-bottom:
        1px solid rgba(114, 231, 255, 0.10) !important;

    backdrop-filter:
        blur(16px);
}


/* ========================================================
   CARDS
   ======================================================== */

article,
.card,
[class*="card"],
[class*="panel"] {
    background:
        linear-gradient(
            145deg,
            rgba(22, 32, 44, 0.82),
            rgba(12, 19, 28, 0.88)
        ) !important;

    border:
        1px solid var(--border) !important;

    border-radius:
        14px !important;

    box-shadow:
        0 12px 35px rgba(0, 0, 0, 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.025);

    backdrop-filter:
        blur(14px);
}


/* ========================================================
   INPUTS
   ======================================================== */

input,
textarea,
select {
    background:
        rgba(8, 14, 21, 0.88) !important;

    color:
        var(--text-main) !important;

    border:
        1px solid rgba(114, 231, 255, 0.15) !important;

    border-radius:
        10px !important;

    box-shadow:
        inset 0 0 12px rgba(0, 0, 0, 0.25);

    outline:
        none !important;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}


input::placeholder,
textarea::placeholder {
    color:
        var(--text-muted) !important;
}


input:focus,
textarea:focus,
select:focus {
    border-color:
        rgba(114, 231, 255, 0.55) !important;

    box-shadow:
        0 0 0 2px rgba(114, 231, 255, 0.06),
        0 0 16px rgba(114, 231, 255, 0.14) !important;
}


/* ========================================================
   BUTTONS
   ======================================================== */

button,
input[type="button"],
input[type="submit"] {
    background:
        linear-gradient(
            145deg,
            rgba(25, 36, 49, 0.95),
            rgba(15, 23, 33, 0.95)
        ) !important;

    color:
        var(--text-main) !important;

    border:
        1px solid rgba(114, 231, 255, 0.15) !important;

    border-radius:
        9px !important;

    box-shadow:
        0 5px 15px rgba(0, 0, 0, 0.20);

    transition:
        all 0.2s ease;
}


button:hover,
input[type="button"]:hover,
input[type="submit"]:hover {
    border-color:
        rgba(114, 231, 255, 0.42) !important;

    box-shadow:
        0 0 16px rgba(114, 231, 255, 0.13);

    transform:
        translateY(-1px);
}


/* ========================================================
   CODE / CSS EDITOR
   ======================================================== */

pre,
code,
textarea,
.CodeMirror,
.cm-editor {
    background:
        #080d14 !important;

    color:
        #9eeaff !important;

    border-color:
        rgba(114, 231, 255, 0.12) !important;
}


/* ========================================================
   SELECTION
   ======================================================== */

::selection {
    background:
        rgba(114, 231, 255, 0.25) !important;

    color:
        #ffffff !important;
}


/* ========================================================
   DIVIDERS
   ======================================================== */

hr {
    border:
        none !important;

    height:
        1px !important;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(114, 231, 255, 0.28),
            rgba(185, 156, 255, 0.28),
            transparent
        ) !important;
}


/* ========================================================
   SCROLLBAR
   ======================================================== */

::-webkit-scrollbar {
    width:
        10px;

    height:
        10px;
}


::-webkit-scrollbar-track {
    background:
        #070b10;
}


::-webkit-scrollbar-thumb {
    background:
        linear-gradient(
            180deg,
            rgba(114, 231, 255, 0.38),
            rgba(185, 156, 255, 0.38)
        );

    border:
        2px solid #070b10;

    border-radius:
        10px;
}


::-webkit-scrollbar-thumb:hover {
    background:
        linear-gradient(
            180deg,
            rgba(114, 231, 255, 0.65),
            rgba(185, 156, 255, 0.65)
        );
}


/* ========================================================
   AMBIENT NEON
   ======================================================== */

body::before {
    content:
        "";

    position:
        fixed;

    inset:
        0;

    pointer-events:
        none;

    z-index:
        999999;

    background:
        radial-gradient(
            circle at 15% 25%,
            rgba(114, 231, 255, 0.025),
            transparent 25%
        ),
        radial-gradient(
            circle at 85% 70%,
            rgba(185, 156, 255, 0.025),
            transparent 25%
        );
}


/* ========================================================
   TOP NEON ACCENT
   ======================================================== */

body::after {
    content:
        "";

    position:
        fixed;

    top:
        0;

    left:
        0;

    right:
        0;

    height:
        1px;

    pointer-events:
        none;

    z-index:
        999999;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(114, 231, 255, 0.35),
            rgba(185, 156, 255, 0.35),
            transparent
        );

    box-shadow:
        0 0 12px rgba(114, 231, 255, 0.15);
}
}
